UPDATE t_workflow_definition_version SET graph_json = #{row.graphJson}, start_form_json = #{row.startFormJson},
        version = version + 1, updated_by = #{row.updatedBy}, update_time = #{row.updateTime}
        WHERE definition_version_id = #{row.definitionVersionId} AND version = #{row.version} AND status = 'DRAFT'
